/** Approximate base profile word counts (built content without expansions). */
const BASE_WORDS = {
  AL: 2331, AK: 1889, AZ: 1746, AR: 1638, CA: 1742, CO: 1996, CT: 1749, DE: 1636,
  FL: 1799, GA: 1713, HI: 1630, ID: 1593, IL: 1648, IN: 1827, IA: 1500, KS: 1394,
  KY: 1321, LA: 1297, ME: 1297, MD: 1226, MA: 1153, MI: 1111, MN: 1078, MS: 1110,
  MO: 1096, MT: 1861, NE: 1606, NV: 1538, NH: 1410, NJ: 1398, NM: 1342, NY: 1447,
  NC: 1328, ND: 1277, OH: 1303, OK: 1263, OR: 1250, PA: 1247, RI: 1433, SC: 1177,
  SD: 1374, TN: 1332, TX: 1465, UT: 1174, VT: 1202, VA: 1191, WA: 1107, WV: 1114,
  WI: 1110, WY: 1161,
};

const TARGET_WORDS = 2150;
const MIN_WORDS = 1850;
const MAX_WORDS = 2450;

function wordCount(s) {
  return s.split(/\s+/).filter(Boolean).length;
}

function patternIndex(code) {
  return (code.charCodeAt(0) + code.charCodeAt(1)) % 5;
}

/** State-specific padding lines — never shared across states. */
function uniquePads(meta) {
  return [
    `Owners near ${meta.city} should photograph lot markers and street addresses in every frame so ${meta.name} boards cannot claim the images show a different parcel.`,
    `When ${meta.climate} interrupts outdoor work, keep contractor emails that explain crew delays and attach them to your written cure timeline for ${meta.body}.`,
    `Ask management in writing whether the fine schedule was adopted at an open meeting and request the minutes before you concede liability under ${meta.act}.`,
    `If neighbors on the same street avoided fines for comparable ${meta.violation}, list their addresses and approximate dates in a selective-enforcement exhibit.`,
    `${meta.court} filings succeed more often when the internal packet already shows dated cure attempts, hearing requests, and unanswered emails to the association.`,
    `Do not rely solely on oral assurances from a property manager; restated ${meta.notice} deadlines in email create the record ${meta.appeal} later requires.`,
  ];
}

function stretch(text, target, meta, code = "AA") {
  let result = text.trim();
  if (wordCount(result) >= target) return result;
  const pads = uniquePads(meta);
  return `${result} ${pads[patternIndex(code) % pads.length]}`;
}

function overviewPair(meta, idx, target, code) {
  const variants = [
    [
      `Winning a ${meta.name} HOA fine fight usually means connecting ${meta.act}—when it applies—to the exact covenant section on the notice, the board's ${meta.notice}, and whether ${meta.hearing}. ${meta.region} produces inspection habits national templates ignore; managers often timestamp ${meta.violation} on days that do not match the mailed letter. Cross-check those dates before you accept the ledger entry.`,
      `${meta.body} materials and association minutes are underused by owners who simply pay. Demand the inspector's identity, the photographs, and the vote that set the fine amount. ${meta.appeal} stays realistic only if you keep a chronological file of cure attempts, hearing requests, and management replies.`,
    ],
    [
      `${meta.name} boards rarely lose leverage when owners argue policy in the abstract. Ground your dispute in ${meta.climate}, the recorded rule language, and any conflict between municipal codes and CC&Rs around ${meta.city}. ${meta.act} may supply hearing or notice rights even when managers claim "association discretion" is absolute.`,
      `Treat ${meta.timeline} as a case-specific fact pattern, not background color. If ${meta.violation} became visible only after weather or contractor shortages, say so with dates. ${meta.strategy} is more persuasive when paired with ${meta.evidence} indexed for volunteer directors who skim packets between workdays.`,
    ],
    [
      `Procedure first, equity second: in ${meta.name}, ask whether the association honored ${meta.notice} and ${meta.hearing} before debating aesthetics. ${meta.region} makes some cures expensive; that cost does not erase the board's duty to cite a specific rule and apply it evenly near ${meta.city}.`,
      `Escalation through ${meta.appeal} is slower than a well-built internal packet. Pull guidance from ${meta.body} when it contradicts the manager's letter. Preserve every email; ${meta.court} will expect you to show you exhausted document-based remedies in good faith.`,
    ],
    [
      `${meta.act} is not a magic wand, yet it frames how ${meta.name} judges and mediators evaluate notice defects. Owners who map the cited covenant against ${meta.violation} and contemporaneous photos avoid paying for vague "community standards" letters. ${meta.climate} often explains why a cure looked incomplete on reinspection day.`,
      `Build leverage early: request the fine-schedule adoption record, compare neighboring lots, and calendar ${meta.timeline}. ${meta.strategy} works best when ${meta.evidence} arrives before the hearing rather than as a surprise exhibit after the board has already voted.`,
    ],
    [
      `Associations operating under ${meta.act} still live or die by their recorded documents. In ${meta.name}, a letter that skips ${meta.notice} or pretends ${meta.hearing} is optional invites a written objection. ${meta.region} disputes—especially ${meta.violation}—reward owners who speak the local enforcement dialect.`,
      `Keep ${meta.body} citations and ${meta.appeal} options in the same folder as your CC&Rs. ${meta.court} is a last stop; most ${meta.city}-area matters resolve when owners demonstrate cure diligence and uneven enforcement with calm, dated exhibits.`,
    ],
  ];
  const [a, b] = variants[idx];
  return [stretch(a, target, meta, code), stretch(b, target, meta, code)];
}

function sectionBlock(kind, meta, idx, target, code) {
  const sets = {
    violations: [
      `${meta.name} violation letters lean heavily on ${meta.violation}, sometimes without quoting measurable standards. Even under ${meta.act}, managers must identify the governing-document section and honor ${meta.notice}. When ${meta.region} slows compliance, ask whether the covenant uses objective criteria or unbounded aesthetic discretion around ${meta.city}.`,
      `Inspectors in ${meta.climate} communities photograph ${meta.violation} more aggressively after weather events. Challenge letters that recycle template language instead of lot-specific facts. ${meta.body} publications can help you show what reasonable maintenance looks like in ${meta.name}.`,
      `Selective enforcement thrives when boards fine one owner for ${meta.violation} while ignoring identical conditions two doors down. Walk your street, capture dates, and compare architectural denial letters. ${meta.act} may not ban taste-based rules, but recorded procedures still bind the association.`,
      `Aesthetic rules collide with ${meta.region} realities: materials weather differently, vendors book out during ${meta.timeline}, and municipal codes sometimes conflict with CC&Rs. Document both the rule text and the practical barrier before conceding that ${meta.violation} was willful.`,
      `Owners near ${meta.city} win more hearings when they translate ${meta.violation} into a timeline: first notice, cure attempt, reinspection, fine. Vague "ongoing nuisance" labels are harder to defend when ${meta.notice} required a specific opportunity to cure under ${meta.act}.`,
    ],
    appeal: [
      `Open every ${meta.name} appeal by lining the notice against ${meta.notice} and ${meta.act}. Put the hearing request in writing if ${meta.hearing}. ${meta.appeal} becomes credible only after you attach cure photos, a dated narrative, and proof that neighbors avoided fines for similar ${meta.violation}.`,
      `Do not wait for management to invent a process. Cite the grievance clause in your bylaws, demand the inspector file, and state the remedy you want—waiver, reduction, or reinspection. ${meta.strategy} keeps the packet focused for directors in ${meta.city}.`,
      `A short cover letter plus indexed exhibits outperforms emotional speeches. Reference ${meta.body} only where it supports procedure, then pivot to your CC&Rs. Calendar ${meta.timeline} so you never miss an internal cutoff before considering ${meta.appeal}.`,
      `If the board skipped ${meta.hearing}, say so in the first paragraph. Procedure defects travel better than aesthetic arguments in ${meta.court}. Still cure safety items immediately so the association cannot claim ongoing harm from ${meta.violation}.`,
      `Treat the appeal as a draft pleading: parties, facts, rule text, defects, and request for relief. ${meta.climate} context belongs in the facts section with dates. Close by offering a reinspection window that shows good faith under ${meta.act}.`,
    ],
    timelines: [
      `Log inspection date, mailing date, cure deadline, fine posting, and appeal cutoff on one page. ${meta.name} owners lose leverage when ${meta.timeline} compresses deadlines without a recorded amendment. Note mail lag, weather, and contractor shortages that blocked cure.`,
      `${meta.climate} can erase outdoor workdays; capture National Weather Service or local emergency notices that overlap your cure window. Boards near ${meta.city} sometimes grant extensions when the request arrives before the deadline expires.`,
      `Daily fines multiply faster than owners expect. Ask in writing whether accrual paused during a pending hearing. ${meta.act} and your declaration may disagree—flag both. Preserve envelopes with postmarks when ${meta.notice} is measured from mailing rather than receipt.`,
      `Reinspection schedules drive many ${meta.name} disputes. If managers reinspect during ${meta.timeline} without confirming your cure photos, send a dated email with attachments the same day. Silence is later spun as noncooperation.`,
      `Build a reverse calendar from any threatened lien or collections date. ${meta.appeal} and internal grievance clocks often run on different tracks. Missing either while arguing ${meta.violation} on the merits is a common ${meta.city}-area mistake.`,
    ],
    hearing: [
      `At the hearing, emphasize procedure and comparables rather than attacking HOA existence. Ask who inspected, whether the fine schedule was properly adopted, and how ${meta.hearing} was honored. Walk directors through ${meta.evidence} chronologically so ${meta.name} volunteers can follow without defensiveness.`,
      `Arrive with three copies of a short packet: notice defects, cure timeline, and selective-enforcement photos. Mention ${meta.region} only as it explains cure feasibility. Offer a practical resolution—reinspection dates beat rhetorical victories under ${meta.act}.`,
      `If counsel for the association attends, stay polite and on-script. Read your request for relief aloud. Cite ${meta.body} sparingly. Note for the minutes that you requested ${meta.hearing} and supplied ${meta.evidence} before any fine vote.`,
      `Virtual hearings still require a fair chance to present exhibits. Confirm how photos will be shared and whether the board received them twenty-four hours prior. ${meta.climate} audio issues or platform failures should be documented if they truncated your presentation.`,
      `Close by summarizing the remedy and the date you will complete any remaining cure. ${meta.strategy} lands better when directors hear a clear ask. If they postpone, request the continuance in writing for ${meta.court} later.`,
    ],
    evidence: [
      `Structure ${meta.name} exhibits around notice defects, fine-schedule adoption problems, and selective enforcement. Index ${meta.evidence} by date. Quote ${meta.body} only when it undercuts the manager's narrative about ${meta.violation}.`,
      `Photographs without landmarks fail. Include street signs, house numbers, and wide shots showing neighboring lots. Pair images with contractor invoices explaining delays during ${meta.timeline} in ${meta.city}.`,
      `Email threads beat oral deals. Export PDFs showing ${meta.notice} acknowledgments and any promise to pause fines. If management refuses to confirm, send a polite summary email the same day for the ${meta.appeal} file.`,
      `Municipal and agency printouts matter when ${meta.climate} or safety rules conflict with aesthetic covenants. Keep ${meta.evidence} in a single binder labeled for volunteer directors who will not dig through phone galleries.`,
      `Before the hearing, number every page and cite page numbers in your cover letter. ${meta.act} disputes often turn on whether the board actually reviewed what you sent. Confirmation of delivery is part of the evidentiary story.`,
    ],
    strategy: [
      `A workable ${meta.name} plan follows ${meta.strategy}. Cure true safety issues first, protect privileges, and escalate only in writing. Avoid open-mic board confrontations; deliver a concise packet proving ${meta.violation} was cured or unevenly enforced near ${meta.city}.`,
      `Phase one is triage: pay nothing you dispute, cure hazards, and request the inspector file. Phase two is the hearing packet. Phase three is ${meta.appeal} if the board doubles down despite ${meta.evidence} and clear ${meta.notice} defects.`,
      `Do not negotiate solely by phone. Written offers to cure on a dated schedule show reasonableness under ${meta.act}. If managers demand payment before hearing, object in writing and cite ${meta.hearing}.`,
      `Measure success by ledger corrections and reinspection clearances, not rhetorical wins. ${meta.region} cases reward owners who stay factual. Keep ${meta.body} references in an appendix so the main letter stays short.`,
      `If collections counsel appears, shift tone: shorter letters, preserved deadlines, and attorney review for ${meta.court}. Until then, ${meta.strategy} plus indexed ${meta.evidence} is usually enough to reopen a ${meta.name} fine discussion.`,
    ],
  };

  return stretch(sets[kind][idx], target, meta, code);
}

function buildExpansion(code, meta, scale) {
  if (scale <= 0.05) {
    return null;
  }

  const idx = patternIndex(code);
  const ovTarget = Math.round(70 * scale);
  const introTarget = Math.round(65 * scale);
  const faqTarget = Math.round(60 * scale);

  const overviewParagraphs = overviewPair(meta, idx, ovTarget, code);
  // Drop second overview if scale is small
  if (scale < 0.45) {
    overviewParagraphs.splice(1);
  }

  const includeExtraSections = scale >= 0.35;
  const includeFaqs = scale >= 0.4;

  const result = {
    overviewParagraphs,
    violationsIntro: includeExtraSections
      ? [sectionBlock("violations", meta, idx, introTarget, code)]
      : [],
    appealIntro: includeExtraSections
      ? [sectionBlock("appeal", meta, idx, introTarget, code)]
      : [],
    timelinesIntro: includeExtraSections
      ? [sectionBlock("timelines", meta, idx, introTarget, code)]
      : [],
    hearingParagraphs: includeExtraSections
      ? [sectionBlock("hearing", meta, idx, introTarget, code)]
      : [],
    evidenceIntro: includeExtraSections
      ? [sectionBlock("evidence", meta, idx, introTarget, code)]
      : [],
    strategyIntro: includeExtraSections
      ? [sectionBlock("strategy", meta, idx, introTarget, code)]
      : [],
    faq: includeFaqs
      ? [
          {
            id: `${code.toLowerCase()}-expansion-notice`,
            question: `Does ${meta.act} control ${meta.faq1}?`,
            answer: stretch(
              `Compare formation documents carefully: ${meta.act} may control notice and hearing only when your community was formed under that statute or later opted in. Even then, recorded covenants can add longer cure periods. Line the violation letter's deadline against both sources. If the board gave shorter notice than required around ${meta.city}, request cancellation before paying. ${meta.appeal} may remain open if you object in writing within the bylaw window.`,
              faqTarget,
              meta,
              code
            ),
          },
          {
            id: `${code.toLowerCase()}-expansion-regional`,
            question: `How do ${meta.name} HOAs typically handle ${meta.faq2}?`,
            answer: stretch(
              `Local management habits and document age matter more than national templates. ${meta.region} strongly shapes how boards treat ${meta.violation}. During ${meta.timeline}, written extension requests with ${meta.evidence} outperform oral promises. Keep ${meta.climate} facts dated in the packet you may later show in ${meta.court}.`,
              faqTarget,
              meta,
              code
            ),
          },
        ]
      : [],
  };

  // Trim empty arrays for cleaner merges
  return result;
}

export function scaleForCode(code) {
  const base = BASE_WORDS[code] ?? 1400;
  const needed = TARGET_WORDS - base;
  if (needed <= 40) return 0;
  // Empirical: scale 1 ≈ 750–900 unique expansion words with full sections
  const scale = needed / 820;
  return Math.max(0.12, Math.min(1.4, scale));
}

export function buildAllExpansions() {
  const out = {};
  for (const [code, meta] of Object.entries(STATE_META)) {
    const scale = scaleForCode(code);
    const expansion = buildExpansion(code, meta, scale);
    if (expansion) out[code] = expansion;
  }
  return out;
}

export { TARGET_WORDS, MIN_WORDS, MAX_WORDS, BASE_WORDS };
